(()=>{"use strict";function createSignEntry(host,doc){const state={phase:"preparing",released:0,checks:0};let timer=0,started=0;const q=id=>doc.getElementById(id);function message(phase,text){doc.documentElement.setAttribute("data-sign-entry",phase);const status=q("cp025Engine");if(!status)return;status.setAttribute("data-entry-status",phase);if(status.textContent!==text)status.textContent=text}function busy(){return!!(host.NCYCP025?.state?.r2Calculating||host.NCYSignR4?.state?.busy||host.NCYCP029?.state?.searching||host.NCYCP029?.state?.applying)}function check(){if(state.phase==="ready"||state.phase==="error")return;host.clearTimeout(timer);timer=0;state.checks++;const ready=host.NCYCP025?.state?.ready&&host.NCYSignR4?.state?.ready;if(ready&&!busy()){for(const node of doc.querySelectorAll("[data-sign-initial-lock]")){node.inert=false;node.removeAttribute("inert");node.removeAttribute("data-sign-initial-lock")}state.phase="ready";state.released++;message("ready","พร้อมกรอกข้อมูลและคำนวณ");return}if(!host.NCYCP025?.state?.ready&&q("cp025Engine")?.classList.contains("bad")){state.phase="error";message("error","เชื่อมหน้ากรอกไม่สำเร็จ โปรดปิดแล้วเปิดไฟล์นี้ใหม่");return}const late=host.performance.now()-started>=15e3;state.phase=late?"delayed":"preparing";message(state.phase,ready?"กำลังทำงาน รอให้เสร็จก่อนแก้ข้อมูล":late?"ช่องกรอกยังเชื่อมไม่ครบ กำลังตรวจต่อ หากยังไม่พร้อมให้ปิดแล้วเปิดไฟล์ใหม่":"กำลังเชื่อมช่องกรอก ปุ่มจะพร้อมเมื่อเชื่อมเสร็จ");timer=host.setTimeout(check,late?1e3:50)}function start(){started=host.performance.now();check()}if(doc.readyState==="loading")doc.addEventListener("DOMContentLoaded",start,{once:true});else start();return Object.freeze({state})}window.NCYSignEntry=createSignEntry(window,document)})();
